// Enumerate sorted unlabeled six-cell mask multisets modulo the 48 label actions on the retained cube skeleton. A cell contained in a saturated-by-skeleton 4-mask is impossible. Multiset row sums are fixed (=3 per label). Use canonical representatives at each size (orderly parent: generate arbitrary augmentations from canonical size-k parents; accept a sorted extension only if canonical. Lex-min sorted lists have lex-min prefixes). Enforce all predecessor order bounds on partial lists. Output final canonical masks to stdout.
#include <algorithm>
#include <array>
#include <vector>
#include <iostream>
using namespace std;int pc(int x){return __builtin_popcount((unsigned)x);}int fixedmask[]={1,2,3,4,6,8,9,12,16,24,32,33,48,64,66,96,128,132,144,192};int cap[]={0,1,3,5,8,12,16,19,26};vector<int> rems[256],opts;int lefts[256];vector<array<int,256>> group;long long countlev[7]={},labeled=0;int cur[6];
void dfs(int d,int lo,int one,int two,int three){countlev[d]++;if(d==6){int stab=0;for(auto &p:group){int buf[6];for(int j=0;j<6;j++)buf[j]=p[cur[j]];sort(buf,buf+6);stab+=equal(buf,buf+6,cur);}labeled+=48/stab;for(int j=0;j<6;j++)cout<<cur[j]<<(j==5?'\n':' ');return;}int need=(d==5?~three:d==4?~two:d==3?~one:0)&255;for(int m:opts){if(m<lo||(m&three)||(m&need)!=need)continue;bool ok=true;for(int t:rems[m])if(!lefts[t]){ok=false;break;}if(!ok)continue;cur[d]=m;for(auto &p:group){int buf[6];for(int j=0;j<=d;j++)buf[j]=p[cur[j]];sort(buf,buf+d+1);if(lexicographical_compare(buf,buf+d+1,cur,cur+d+1)){ok=false;break;}}if(!ok)continue;for(int t:rems[m])--lefts[t];dfs(d+1,m,one|m,two|(one&m),three|(two&m));for(int t:rems[m])++lefts[t];}}
int main(){array<int,8> perm={0,1,2,3,4,5,6,7};do{array<int,256> p={};for(int i=1;i<256;i++)p[i]=p[i&(i-1)]|(1<<perm[__builtin_ctz(i)]);bool ok=true;for(int m:fixedmask)if(find(begin(fixedmask),end(fixedmask),p[m])==end(fixedmask))ok=false;if(ok)group.push_back(p);}while(next_permutation(perm.begin(),perm.end()));if(group.size()!=48)return 1;for(int t=0;t<256;t++){lefts[t]=cap[pc(t)];for(int m:fixedmask)lefts[t]-=!(m&~t);}for(int m=1;m<256;m++){bool ok=true;for(int t=m;t<256;t++)if(!(m&~t)){if(!lefts[t])ok=false;rems[m].push_back(t);}if(ok)opts.push_back(m);}dfs(0,1,0,0,0);for(auto v:countlev)cerr<<v<<' ';cerr<<"labeled "<<labeled<<'\n';}
